def find_project_root(start):
    if os.path.isfile(os.path.join(start, "package.json")) and \
       os.path.isfile(os.path.join(start, "src", "App.tsx")):
        return start
    for root, dirs, files in os.walk(start):
        depth = root[len(start):].count(os.sep)
        if depth >= 3:
            dirs[:] = []
            continue
        if "package.json" in files and os.path.isfile(os.path.join(root, "src", "App.tsx")):
            return root
    return None


def write_full_files(project_dir):
    for rel_path, content in DATA["full_files"].items():
        full_path = os.path.join(project_dir, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with io.open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"[ok] {rel_path}: انكتب ({len(content)} حرف)")


def apply_patches(project_dir):
    for rel_path, patch_list in DATA["patches"].items():
        full_path = os.path.join(project_dir, rel_path)
        with io.open(full_path, "r", encoding="utf-8") as f:
            content = f.read()

        for i, change in enumerate(patch_list):
            if change["new"] in content:
                print(f"[skip] {rel_path} patch {i+1}/{len(patch_list)}: موجود مسبقاً")
                continue

            count = content.count(change["old"])
            if count == 0:
                print(f"[FAIL] {rel_path} patch {i+1}/{len(patch_list)}: ما لقيت النص المطلوب تبديله (الملف يمكن يكون اتغيّر عن الأصل)")
                continue
            if count > 1:
                print(f"[FAIL] {rel_path} patch {i+1}/{len(patch_list)}: النص تكرر {count} مرة - تجاوزت هذا التعديل")
                continue

            content = content.replace(change["old"], change["new"], 1)
            print(f"[ok] {rel_path} patch {i+1}/{len(patch_list)}: انعدّل")

        with io.open(full_path, "w", encoding="utf-8") as f:
            f.write(content)


def main():
    project_dir = find_project_root(PROJECT_DIR_GUESS)
    if not project_dir:
        print(f"[X] ما لقيت مشروع صحيح تحت {PROJECT_DIR_GUESS}")
        manual = input("اكتب المسار الكامل الصحيح للمشروع: ").strip()
        project_dir = find_project_root(os.path.expanduser(manual))
        if not project_dir:
            print("[X] ولا هذا المسار فيه مشروع صحيح. وقفت.")
            sys.exit(1)

    print(f"مجلد المشروع: {project_dir}")

    write_full_files(project_dir)
    apply_patches(project_dir)

    print()
    print("خلص! راجع git diff قبل ما تعمل push.")
    print("لا تنسى:")
    print("1) تشغل ملف games_attempts_migration.sql بلوحة Supabase (SQL Editor).")
    print("2) تسوي وحدة إعلانية جديدة بلوحة Adsgram وتحط رقمها بدل ADSGRAM_GAMES_BLOCK_ID بملف src/App.tsx (حالياً يستخدم نفس وحدة Stars مؤقتاً).")


if __name__ == "__main__":
    main()
